# -*- coding: utf-8 -*-
"""Catalogo "Popular trips": viaggi classici e molto richiesti di 10-12 giorni ad agosto, anche multi-paese e open-jaw.

Ogni trip:
  id, name, countries, area, type ("oj" = open-jaw, "rt" = andata e ritorno), arr / dep (aeroporto di arrivo / ripartenza),
  stages [(luogo, notti, cosa)], ground (mezzi a terra), internal [(tratta, stima € pp)] = voli interni necessari comunque,
  land (min, max) = costo a terra stimato pp mid-range in camera doppia (alloggi, pasti, auto/driver, ingressi, attività; voli esclusi),
  style (tag), pace, hi (highlight), aug (nota agosto), g (clima: ottimo|buono|accettabile), temp,
  visited (paese già visto -> giro in zone nuove), seen, flag,
  air = modi di volare, il build sceglie il più economico per ogni data:
     ("oj", arr, dep)                      open-jaw: Milano->arr e dep->Milano (somma di 2 solo-andata, stima)
     ("rt", hub, [(tratta, stima)], nota)  A/R reale su hub + eventuali tratte extra stimate per chiudere il giro

Le stime (voli interni, costo a terra) sono ordini di grandezza per agosto in alta stagione, non preventivi.
"""

def T(id, name, countries, area, type, arr, dep, stages, ground, internal, land, style, pace, hi, aug, g, temp, air,
      visited=False, seen=None, flag=None, src=None):
    return {"id": id, "name": name, "countries": countries, "area": area, "type": type, "arr": arr, "dep": dep,
            "stages": stages, "ground": ground, "internal": internal, "land": land, "style": style, "pace": pace,
            "hi": hi, "aug": aug, "g": g, "temp": temp, "air": air, "visited": visited, "seen": seen, "flag": flag, "src": list(src or SRC.get(id, []))}

